# --- 자동 생성 끝: blastoise ---

POKEMON = {p.key: p for p in (PIKACHU, CHARMANDER, BULBASAUR, SQUIRTLE, DITTO, MEW, WARTORTLE, IVYSAUR, VENUSAUR, CHARMELEON, CHARIZARD, RAICHU, BLASTOISE)}

# 진화: 왼쪽 포켓몬을 아껴 주면 오른쪽 포켓몬이 된다.
#
# 도트는 자동 생성 구역 안에 들어가므로, 진화 관계는 그 바깥인 여기에 적는다.
# 그림을 다시 들여와도 이 표는 지워지지 않는다.
EVOLUTIONS = {
    "bulbasaur": "ivysaur",
    "ivysaur": "venusaur",
    "charmander": "charmeleon",
    "charmeleon": "charizard",
    "squirtle": "wartortle",
    "wartortle": "blastoise",
    "pikachu": "raichu",
}

for _from, _into in EVOLUTIONS.items():
    POKEMON[_from].evolves_to = _into

# 진화해야 만날 수 있는 포켓몬. 메뉴의 '포켓몬 추가' 에는 넣지 않는다.
EVOLVED_ONLY = frozenset(EVOLUTIONS.values())


def base_species():
    """처음부터 고를 수 있는 포켓몬들(진화체 제외)."""
    return [key for key in POKEMON if key not in EVOLVED_ONLY]


def validate_all():
    """모든 스프라이트 데이터가 정상인지 확인한다."""
    for pokemon in POKEMON.values():
        pokemon.validate()
        frames = pokemon.frames()
        widths = {len(row) for frame in frames for row in frame}
        heights = {len(frame) for frame in frames}
        if len(widths) != 1 or len(heights) != 1:
            raise ValueError("%s: 프레임 크기가 서로 다릅니다" % pokemon.key)
        if len(frames) < 2:
            raise ValueError("%s: 프레임이 2장 이상이어야 합니다" % pokemon.key)
        if pokemon.move == "hop" and len(frames) < 3:
            raise ValueError(
                "%s: 뛰어다니는 포켓몬은 [평소, 웅크림, 늘어남] 3장이 필요합니다" % pokemon.key
            )
        if pokemon.evolves_to is not None:
            if pokemon.evolves_to not in POKEMON:
                raise ValueError(
                    "%s: 모르는 포켓몬으로 진화합니다: %s" % (pokemon.key, pokemon.evolves_to)
                )
            if pokemon.evolves_to == pokemon.key:
                raise ValueError("%s: 자기 자신으로 진화할 수는 없습니다" % pokemon.key)
    return True


if __name__ == "__main__":
    validate_all()
    for pokemon in POKEMON.values():
        frame = pokemon.frames()[0]
        print("%s (%s) %dx%d, %d프레임, x%.2f" % (
            pokemon.name_ko, pokemon.key, len(frame[0]), len(frame),
            len(pokemon.frames()), pokemon.scale_factor,
        ))
